import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_cpp_src = "torch::Tensor conv3x3_bf16(torch::Tensor x, torch::Tensor w);"

_cuda_src = r'''
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAException.h>
#include <cuda_bf16.h>
#include <cuda_runtime.h>

namespace {

constexpr int IN_C = 3;
constexpr int OUT_C = 32;
constexpr int K = 3;
constexpr int TILE_X = 32;
constexpr int TILE_Y = 16;
constexpr int SX = TILE_X + K - 1;  // 34
constexpr int SY = TILE_Y + K - 1;  // 18

__global__ void conv3x3_bf16_kernel(
    const __nv_bfloat16* __restrict__ x,
    const __nv_bfloat16* __restrict__ w,
    __nv_bfloat16* __restrict__ y,
    const int N,
    const int H,
    const int W,
    const int Ho,
    const int Wo) {
  __shared__ __nv_bfloat16 xs[IN_C][SY][SX];
  __shared__ float ws[IN_C * K * K];

  const int tx = threadIdx.x;
  const int ty = threadIdx.y;
  const int tid = ty * blockDim.x + tx;

  const int ow0 = blockIdx.x * TILE_X;
  const int oh0 = blockIdx.y * TILE_Y;

  const int nz = blockIdx.z;
  const int n = nz / OUT_C;
  const int oc = nz % OUT_C;

  if (tid < IN_C * K * K) {
    ws[tid] = __bfloat162float(w[(size_t)oc * (IN_C * K * K) + tid]);
  }

  const size_t x_base = (size_t)n * IN_C * H * W;
  constexpr int TILE_ELEMS = IN_C * SY * SX;
  constexpr int THREADS = TILE_X * TILE_Y;

  for (int idx = tid; idx < TILE_ELEMS; idx += THREADS) {
    const int c = idx / (SY * SX);
    const int rem = idx % (SY * SX);
    const int yy = rem / SX;
    const int xx = rem % SX;

    const int ih = oh0 + yy;
    const int iw = ow0 + xx;

    __nv_bfloat16 v = __float2bfloat16(0.0f);
    if (ih >= 0 && ih < H && iw >= 0 && iw < W) {
      v = x[x_base + ((size_t)c * H + ih) * W + iw];
    }
    xs[c][yy][xx] = v;
  }

  __syncthreads();

  const int oh = oh0 + ty;
  const int ow = ow0 + tx;

  if (oh < Ho && ow < Wo) {
    float acc = 0.0f;

    #pragma unroll
    for (int c = 0; c < IN_C; ++c) {
      #pragma unroll
      for (int ky = 0; ky < K; ++ky) {
        #pragma unroll
        for (int kx = 0; kx < K; ++kx) {
          const float xv = __bfloat162float(xs[c][ty + ky][tx + kx]);
          acc = fmaf(xv, ws[c * 9 + ky * 3 + kx], acc);
        }
      }
    }

    y[(((size_t)n * OUT_C + oc) * Ho + oh) * Wo + ow] = __float2bfloat16(acc);
  }
}

}  // namespace

torch::Tensor conv3x3_bf16(torch::Tensor x, torch::Tensor w) {
  TORCH_CHECK(x.is_cuda(), "input must be CUDA");
  TORCH_CHECK(w.is_cuda(), "weight must be CUDA");
  TORCH_CHECK(x.dtype() == at::kBFloat16, "input must be bf16");
  TORCH_CHECK(w.dtype() == at::kBFloat16, "weight must be bf16");
  TORCH_CHECK(x.dim() == 4, "input must be NCHW");
  TORCH_CHECK(w.dim() == 4, "weight must be OIHW");
  TORCH_CHECK(x.size(1) == 3, "expected 3 input channels");
  TORCH_CHECK(w.size(0) == 32 && w.size(1) == 3 && w.size(2) == 3 && w.size(3) == 3,
              "expected weight shape [32, 3, 3, 3]");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  const int64_t N = x_c.size(0);
  const int64_t H = x_c.size(2);
  const int64_t W = x_c.size(3);
  TORCH_CHECK(H >= 3 && W >= 3, "spatial size must be >= 3");

  const int64_t Ho = H - 2;
  const int64_t Wo = W - 2;

  auto y = torch::empty({N, 32, Ho, Wo}, x_c.options());
  if (N == 0 || Ho == 0 || Wo == 0) {
    return y;
  }

  dim3 block(TILE_X, TILE_Y, 1);
  dim3 grid((unsigned)((Wo + TILE_X - 1) / TILE_X),
            (unsigned)((Ho + TILE_Y - 1) / TILE_Y),
            (unsigned)(N * 32));

  const __nv_bfloat16* x_ptr =
      reinterpret_cast<const __nv_bfloat16*>(x_c.data_ptr<at::BFloat16>());
  const __nv_bfloat16* w_ptr =
      reinterpret_cast<const __nv_bfloat16*>(w_c.data_ptr<at::BFloat16>());
  __nv_bfloat16* y_ptr =
      reinterpret_cast<__nv_bfloat16*>(y.data_ptr<at::BFloat16>());

  conv3x3_bf16_kernel<<<grid, block, 0, at::cuda::getCurrentCUDAStream()>>>(
      x_ptr, w_ptr, y_ptr, (int)N, (int)H, (int)W, (int)Ho, (int)Wo);
  C10_CUDA_KERNEL_LAUNCH_CHECK();

  return y;
}
'''

_ops = load_inline(
    name="conv3x3_bf16_custom",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["conv3x3_bf16"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.conv1 = nn.Conv2d(
            in_channels=3,
            out_channels=32,
            kernel_size=3,
            bias=False,
            dtype=torch.bfloat16,
        )

    def forward(self, x):
        return _ops.conv3x3_bf16(x, self.conv1.weight)

